// مكتبة الأيقونات: رموزٌ تُختار لأنواع الفوائد ولتصنيفاتها وفروعها ولأعلامها
// ولكرّاساتها.
//
// ===========================================================================
// لماذا أُعيدت من أصلها
// ===========================================================================
//
// كانت مرسومةً هنا باليد على مربّع ٢٤، رسمًا بالإحداثيّات لا بالعين — فخرج
// كثيرٌ منها لا يُعرف ما هو: «فرسٌ» لا يشبه فرسًا، و«نحلةٌ» دوائرُ متراكبة،
// وفي المُنتقي بطاقاتٌ تُقرأ أسماؤها ولا تُرى رموزُها. والأيقونةُ التي تحتاج
// اسمَها لتُفهم ليست أيقونة.
//
// فصارت على رسمٍ محترف موحَّد: **Phosphor Icons** بوجهها «الثنائيّ اللون»
// (duotone)، وهو عينُ ما كانت تطلبه هذه المكتبة من قبل — جسدٌ مصبوغٌ صبغًا
// خفيفًا وحدٌّ مخطوطٌ فوقه — غير أنه مرسومٌ بيد مصمِّمين على شبكةٍ واحدة،
// ومجرَّبٌ في آلاف المواضع. رخصتُها MIT (© Phosphor Icons)، والمساراتُ
// منقولةٌ إلى هذا الملف نقلًا فلا يُجلب شيءٌ من خارج.
//
// **وما لا مقابلَ له فيها مرسومٌ هنا على قواعدها** (`CUSTOM`): المئذنةُ
// والمحرابُ والمسبحةُ والفانوسُ والشمعةُ والمحبرةُ والنحلةُ وربعُ الحزب
// وخاتما النكاح وشاهدُ القبر ورفُّ الكتب. وقواعدُها: شبكةُ ٢٥٦، والحدُّ خطٌّ
// سُمكُه ١٦ مستديرُ الطرفين، والجسدُ ما أُغلق ويُصبَغ بخُمس اللون، والرسمُ
// بين ٢٤ و٢٣٢ لا يخرج عنها.
//
// ===========================================================================
//
// **وهي ملوَّنة** (`tone`): لكلّ أيقونةٍ لونُها من لوحةٍ ثمانيّة، واللونُ خبرٌ
// لا زينة — تُعرف الأبوابُ في الشبكة بألوانها قبل أن تُقرأ أسماؤها. **واللونُ
// يُرفع حيث يُزاحمه لون** (`plain`): الرُّقعةُ المضغوطة أرضُها لونُ المكتبة.
//
// **وحدُّها يثخن في الصغير** (`weightOf`): الحدُّ في Phosphor سُمكُه ١٦ من
// ٢٥٦، فهو في أيقونةِ ٢٤ بكسلًا بكسلٌ ونصف، وفي أيقونةِ ١١ — حجمِها في رُقعة
// البطاقة — سبعةُ أعشار البكسل: خيطٌ يتقطّع ويشحب. فيُخطّ على الحدّ المصمت
// خطٌّ من لونه بقدر ما نقص، فيبقى المرئيُّ منه واحدًا في الأحجام كلِّها.
//
// **والمفتاحُ (`key`) هو المحفوظ في القاعدة لا الرسم**: بُدِّلت الرسومُ كلُّها
// مرّتين ولم يتغيّر في المستندات حرف، والمفاتيحُ المئةُ والثمانون كلُّها
// باقية. ومفتاحٌ لا رسمَ له يُرسم في المُنتقي دائرةً منقوطة (`placeholder`)،
// ولا يُرسم في البطاقات شيئًا.

import type { CSSProperties } from 'react'

/**
 * ألوانُ الأيقونات. ثمانيةٌ لا أكثر: كثرةُ الألوان في الشبكة الواحدة تُذهب
 * دلالتَها. وقيمتُها في ملف الأنماط (`--ic-*`) لتتبع المظاهرَ الثلاثة.
 */
export type IconTone =
  | 'gold' | 'green' | 'purple' | 'teal' | 'blue' | 'rose' | 'brown' | 'slate'

type Circle = [number, number, number]

/** الرسمُ نفسه، على شبكة ٢٥٦ */
interface IconArt {
  /** الأجسادُ: تُصبَغ بخُمس اللون في طبقةٍ واحدة */
  b?: string[]
  /** الحدودُ المصمتة (رسمُ Phosphor): تُملأ باللون ويُخطّ عليها في الصغير */
  f?: string[]
  /** الخطوطُ (الرسمُ اليدويّ): تُخطّ بسُمك ١٦ */
  s?: string[]
  /** دوائرُ يُخطّ حدُّها ويُصبَغ جوفُها */
  c?: Circle[]
  /** يُعكس أفقيًّا — لرمزٍ يُستعار لمعنيين، فلا يتطابقان في الشبكة */
  flip?: boolean
}

export interface IconDef extends IconArt {
  /** المفتاحُ المحفوظ في القاعدة */
  key: string
  /** اسمُها بالعربية، يُقرأ في المُنتقي ويُبحث به */
  label: string
  group: string
  /** لونُها من اللوحة */
  tone: IconTone
  /** أسماءٌ أخرى يُبحث بها ولا تُعرض: من كتب «حصان» بلغ «فرس» */
  alt?: string
}

