/** حبّاتُ المسبحة: عشرٌ على دائرةٍ نصفُ قطرها ٧٢، أولاها في أسفلها */
const BEADS: Circle[] = Array.from({ length: 10 }, (_, i) => {
  const a = Math.PI / 2 + (i * Math.PI) / 5
  return [Math.round(128 + 72 * Math.cos(a)), Math.round(110 + 72 * Math.sin(a)), 13]
})

