const BY_KEY = new Map(ICONS.map((i) => [i.key, i]))

export function iconByKey(key: string | undefined | null): IconDef | undefined {
  return key ? BY_KEY.get(key) : undefined
}

/** شفافيّةُ الجسد المصبوغ، وهي شفافيّةُ Phosphor نفسُها */
const BODY_ALPHA = 0.2

/** سُمكُ الخطّ في الرسم اليدويّ، على شبكة ٢٥٦ — وهو سُمكُ حدِّ Phosphor */
const LINE = 16

/**
 * ما يُزاد على الحدّ في الأيقونة الصغيرة، على شبكة ٢٥٦.
 *
 * الحدُّ ١٦ من ٢٥٦ يُرى في أيقونةِ ١١ بكسلًا سبعةَ أعشار البكسل، فيتقطّع
 * ويشحب. فيُزاد عليه ما يبلغ به بكسلًا وعُشرًا تقريبًا (٣٠٠ ÷ الحجم)، ولا
 * يُزاد على الكبيرة شيء، ولا يُجاوَز اثنا عشر كي لا تنسدّ الفُرَج في جوفها.
 */
function weightOf(size: number): number {
  return Math.min(12, Math.max(0, 300 / size - LINE))
}

/**
 * رسمُ الأيقونة بمفتاحها.
 *
 * **والرسمُ نوبتان**: تُصبَغ الأجسادُ كلُّها أوّلًا في طبقةٍ واحدة تُشفَّف بعد
 * تسطيحها — فلا يتضاعف الصبغُ حيث يقع جسدٌ على جسد — ثم تُرسم الحدودُ فوقها
 * فلا يغسلها شيء.
 */
export function Icon(
  { name, size = 18, plain, placeholder, style }: {
    name?: string | null
    size?: number
    /**
     * تلبس لونَ موضعها لا لونَها: تُمرَّر في الرُّقعة المضغوطة وفي الشارة
     * المصمتة — أرضُهما لونُ المكتبة، فلونٌ ثانٍ فوقه مزاحمة.
     */
    plain?: boolean
    /**
     * يُرسم مكانَ ما لا أيقونةَ له دائرةٌ منقوطة. وهي في المُنتقي وحده —
     * موضعٌ شاغر يُنادي على من يملؤه — وأمّا في البطاقات فلا: بابٌ بلا رمزٍ
     * يُعرض باسمه، ودائرةٌ فارغة إلى جانبه ضجيجٌ لا خبر.
     */
    placeholder?: boolean
    style?: CSSProperties
  },
) {
  const def = iconByKey(name)
  if (!def && !placeholder) return null
  const color = plain || !def ? 'currentColor' : `var(--ic-${def.tone})`
  const extra = weightOf(size)
  const props = {
    width: size,
    height: size,
    viewBox: '0 0 256 256',
    'aria-hidden': true,
    focusable: false,
    style: { flex: 'none', ...style },
  }
  if (!def) {
    return (
      <svg {...props} fill="none" stroke={color} strokeWidth={LINE + extra} strokeLinecap="round">
        <circle cx="128" cy="128" r="80" strokeDasharray="20 30" />
      </svg>
    )
  }

  const circles = def.c ?? []
  return (
    <svg {...props}>
      <g transform={def.flip ? 'matrix(-1 0 0 1 256 0)' : undefined}>
        {/* النوبةُ الأولى: الأجسادُ في طبقةٍ واحدة */}
        {(def.b?.length || circles.length > 0) && (
          <g opacity={BODY_ALPHA} fill={color}>
            {def.b?.map((d, i) => <path key={i} d={d} />)}
            {circles.map(([cx, cy, r], i) => <circle key={i} cx={cx} cy={cy} r={r} />)}
          </g>
        )}

        {/* والثانيةُ: الحدودُ. المصمتُ يُملأ ويُخطّ عليه بما نقص من سُمكه */}
        {def.f && (
          <g
            fill={color}
            stroke={extra > 0 ? color : undefined}
            strokeWidth={extra || undefined}
            strokeLinejoin="round"
          >
            {def.f.map((d, i) => <path key={i} d={d} />)}
          </g>
        )}
        {(def.s || circles.length > 0) && (
          <g
            fill="none"
            stroke={color}
            strokeWidth={LINE + extra}
            strokeLinecap="round"
            strokeLinejoin="round"
          >
            {def.s?.map((d, i) => <path key={i} d={d} />)}
            {circles.map(([cx, cy, r], i) => <circle key={i} cx={cx} cy={cy} r={r} />)}
          </g>
        )}
      </g>
    </svg>
  )
}
